from pathlib import Path
import sys
_SUBMISSION_ROOT = Path(__file__).resolve().parents[3]
__file__ = str(_SUBMISSION_ROOT / 'repo/ml_training/report_trial.py')
sys.path.insert(0, str(Path(__file__).parent))
sys.path.insert(0, str(_SUBMISSION_ROOT / "repo"))
"""Produce plots, a flowchart, a concise notebook and a report from trial results."""
import os
os.environ.setdefault('MPLBACKEND','Agg')
from pathlib import Path
import json,numpy as np,matplotlib.pyplot as plt,nbformat
from matplotlib.patches import FancyBboxPatch
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'output/ml_small_trial'
r=json.loads((OUT/'results.json').read_text());runs=r['runs'];seeds=[x['seed'] for x in runs]
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False})
blue='#21618C';orange='#D67822';navy='#17354B'
def save(fig,name):
 fig.savefig(OUT/f'{name}.png',dpi=180,bbox_inches='tight',facecolor='white');fig.savefig(OUT/f'{name}.svg',bbox_inches='tight',facecolor='white');plt.close(fig)
fig,axs=plt.subplots(1,3,figsize=(14,4.7));keys=['tumour','overall_healthy','worst_subgroup'];names=['Tumour killing','Overall healthy killing','Worst healthy subgroup']
for ax,key,name in zip(axs,keys,names):
 vals=[a['test_metrics'][key]['mae_pp'] for a in runs];ax.bar(range(len(vals)),vals,color=blue);ax.set_xticks(range(len(vals)),[str(s) for s in seeds]);ax.set_title(name);ax.set_xlabel('Search seed');ax.set_ylabel('Mean absolute error (percentage points)')
 for i,v in enumerate(vals):ax.text(i,v+max(vals)*.03,f'{v:.2f}',ha='center')
 ax.set_ylim(0,max(vals)*1.22)
fig.suptitle('Prediction error on 64 untouched binding-rate combinations',fontsize=17,fontweight='bold');fig.text(.5,.005,'Each combination is evaluated under all three assumed biological conditions. Error is against ODE simulations, not experiments.',ha='center',fontsize=10);fig.tight_layout(rect=[0,.05,1,.94]);save(fig,'prediction_accuracy')
fig,axs=plt.subplots(1,3,figsize=(14,4.8));xx=np.arange(len(runs));w=.36
for ax,key,title in zip(axs,['best_tumour','hypervolume','time'],['Best feasible tumour killing (%)','Coverage of tumour–healthy trade-offs','Elapsed search time (seconds)']):
 a=[v['assisted'][key] if key!='time' else v['timing']['assisted_total_wall'] for v in runs];b=[v['direct'][key] if key!='time' else v['timing']['direct_total_wall'] for v in runs]
 ax.bar(xx-w/2,a,w,label='Regression-assisted',color=orange);ax.bar(xx+w/2,b,w,label='Direct ODE search',color=blue);ax.set_xticks(xx,[str(s) for s in seeds]);ax.set_xlabel('Search seed');ax.set_title(title)
 for i,(u,v) in enumerate(zip(a,b)):
  ax.text(i-w/2,u+max(a+b)*.025,f'{u:.4f}' if key=='hypervolume' else f'{u:.1f}',ha='center',fontsize=9);ax.text(i+w/2,v+max(a+b)*.025,f'{v:.4f}' if key=='hypervolume' else f'{v:.1f}',ha='center',fontsize=9)
 ax.set_ylim(0,max(a+b)*1.22)
axs[0].legend(frameon=False,fontsize=9,loc='upper left');axs[1].set_ylabel('Normalised dominated volume (higher is better)');fig.suptitle('Equal total budgets: 224 combinations per method and seed',fontsize=17,fontweight='bold');fig.text(.5,.005,'Four ODE workers for both methods. Times include initial simulations, model fitting/search and tighter final checks. ML time includes model-selection data. Test costs are reported separately.',ha='center',fontsize=9);fig.tight_layout(rect=[0,.05,1,.94]);save(fig,'search_comparison')
# Scatter for all out-of-sample predictions, preserving seed structure in saved data.
fig,axs=plt.subplots(1,3,figsize=(14,4.7));F=np.array([.79,.1,.1,.01])
def endpoints(y):
 a=np.array(y).reshape(-1,3,5);return np.c_[a[:,:,0].min(1),(a[:,:,1:]@F).max(1),a[:,:,1:].max((1,2))]
for seed in seeds:
 p=json.loads((OUT/f'predictions_{seed}.json').read_text());a=endpoints(p['test_actual']);b=endpoints(p['test_prediction'])
 for j,ax in enumerate(axs):ax.scatter(a[:,j],b[:,j],s=17,alpha=.55,label=str(seed))
for j,ax in enumerate(axs):
 lo,hi=ax.get_xlim();ax.plot([0,hi],[0,hi],color='black',linestyle='--',lw=1);ax.set(xlabel='ODE-calculated killing (%)',ylabel='Regression-predicted killing (%)',title=names[j])
axs[0].legend(title='Search seed',frameon=False);fig.suptitle('How closely did regression reproduce the ODE model?',fontsize=17,fontweight='bold');fig.tight_layout(rect=[0,0,1,.93]);save(fig,'predicted_vs_simulated')
# A presentation-ready methodological flowchart with results generated from this trial.
mae={k:np.mean([a['test_metrics'][k]['mae_pp'] for a in runs]) for k in keys};hva=np.mean([a['assisted']['hypervolume'] for a in runs]);hvd=np.mean([a['direct']['hypervolume'] for a in runs]);ta=np.mean([a['timing']['assisted_total_wall'] for a in runs]);td=np.mean([a['timing']['direct_total_wall'] for a in runs]);models=', '.join(a['selected_model'] for a in runs)
fig,ax=plt.subplots(figsize=(15,10));ax.set_xlim(0,15);ax.set_ylim(0,10);ax.axis('off');ax.text(.4,9.65,'Small trial: regression-assisted binding-rate optimisation',fontsize=22,fontweight='bold',color=navy)
ax.text(.4,9.22,'Four binding rates vary. The existing ODE model and three biological conditions stay fixed.',fontsize=13,color='#526777')
def box(x,y,w,h,title,body):
 ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.04,rounding_size=.08',facecolor='#F3F7FA',edgecolor='#B7C8D5',lw=1));ax.text(x+.16,y+h-.18,title,fontsize=14,fontweight='bold',color=navy,va='top');ax.text(x+.16,y+h-.55,body,fontsize=11.5,color='#263B49',va='top',linespacing=1.5)
def arrow(x1,y1,x2,y2):ax.annotate('',xy=(x2,y2),xytext=(x1,y1),arrowprops=dict(arrowstyle='->',color=navy,lw=1.8))
box(.4,7.35,6.7,1.45,'1  Generate simulated data','64 initial combinations per seed, sampled in log-rate space.\nSolve the ODE for tumour and four healthy subgroups\nunder each of the three conditions. No LLM-generated labels.')
box(.4,5.50,6.7,1.45,'2  Separate data and preprocess','32 validation and 64 untouched test combinations.\nInput z = (log₁₀ binding rate − training mean) / training SD.\nAlso standardise the 15 outputs using training data only.')
box(.4,3.65,6.7,1.45,'3  Compare and select regression models','Train Gaussian-process and extra-trees models.\nChoose by validation error scaled to the objective limits.\nGaussian-process regression won in all three runs.')
box(.4,1.80,6.7,1.45,'4  Set tumour and healthy-cell objectives','Maximise the lowest tumour kill across conditions.\nMinimise the highest overall and subgroup healthy kill.\nRequire overall ≤0.95% and every healthy subgroup ≤10%.')
for y in [7.35,5.5,3.65]:arrow(3.75,y,3.75,y-.40)
box(7.8,7.35,6.7,1.45,'5  Learn from additional ODE simulations','Four rounds of 24 new combinations, then 32 final candidates.\nSample predicted trade-offs, uncertain and unexplored regions.\nRefit after each round. Every selected point gets an ODE label.')
box(7.8,5.50,6.7,1.45,'6  Compare with direct optimisation','ML: 192 search + 32 model-selection combinations.\nDirect: 224 search combinations, including the same initial 64.\nRepeat three seeds and recheck up to 12 designs more tightly.')
box(7.8,3.65,6.7,1.45,'7  Measure prediction accuracy','Mean test error across seeds, in percentage points:\n'+f'Tumour {mae["tumour"]:.2f}     Overall healthy {mae["overall_healthy"]:.2f}\nWorst healthy subgroup {mae["worst_subgroup"]:.2f}')
box(7.8,1.80,6.7,1.45,'8  Measure whether the approach helped',f'Mean trade-off coverage: ML {hva:.3f}, direct {hvd:.3f}.\nMean elapsed time: ML {ta:.0f} s, direct {td:.0f} s.\nThe report includes feasibility errors and tighter ODE checks.')
for y in [7.35,5.5,3.65]:arrow(11.15,y,11.15,y-.40)
ax.plot([7.1,7.45,7.45],[2.5,2.5,8.0],color=navy,lw=1.6);arrow(7.45,8.0,7.8,8.0)
ax.text(.4,.95,'Interpretation: this tests approximation and search efficiency within our assumed model.',fontsize=14,fontweight='bold',color=navy)
ax.text(.4,.50,f"{sum(a['candidate_metrics']['false_feasible'] for a in runs)} predicted-feasible proposals failed ODE limits. Verify final designs with ODEs. Healthy-cell limits are illustrative.",fontsize=11,color='#526777');save(fig,'trial_flowchart')
# Tabulated evidence and full methodological explanation.
lines=['# Small regression-assisted optimisation trial','', 'This completed computational pilot compares regression-assisted search with direct NSGA-II on the unchanged mechanistic model. All labels come from numerical ODE solutions. No experimental or LLM-invented outcomes were used.','', '## Study design','', '- Four adjustable inputs: log10 association and dissociation rates for both targets. Association limits: 10²–10⁷ M⁻¹ s⁻¹. Dissociation limits: 10⁻⁵–10² s⁻¹. These retain the existing search domain, not experimentally established bounds.','- Three existing illustrative biological conditions remain fixed, including target densities, internalisation, linker release, payload exchange, potency and exposure. This is not a model for arbitrary patients or targets.','- Three independent initial samples of 64 combinations. Per seed, both methods use 224 combinations when model selection is counted. Direct search evaluates 224. Regression uses 192 search combinations plus the separate 32 model-selection combinations. Both start with the same initial 64. Regression adds 4 × 24 active-learning candidates and 32 final candidates.','- A separate 32-combination validation set selects the model. A separate 64-combination test set is untouched during fitting, model selection and candidate selection. The same held-out sets serve all seeds, so pooled predictions are not 192 independent test combinations.','', '## Preprocessing and regression','', 'Latin hypercube sampling spans the logarithms of the four rates. Physical rate = 10^(sampled value). KD is derived as koff/kon and is not independently varied. We do not logarithmically transform target densities, so zero-expression groups remain unchanged.','', 'Input standardisation uses z=(log10(rate)−training mean)/training standard deviation. Output standardisation uses training means and standard deviations for the 15 cell-killing outputs (five populations × three conditions). Scalers are refitted on the expanding training set, never on validation or test data. No logit transformation is used. Predictions are clipped to 0–85.34%, the model’s 24-hour maximum at kmax=0.08/h. Clipping does not guarantee accuracy near the constraints.','', 'Models: a Gaussian process with a Matérn 5/2 kernel, shared learned length scales across the 15 outputs, versus 100 extra-trees regressors with minimum leaf size 2. The GP does not learn cross-output covariance. Select the lower validation score: mean(MAE tumour/100, MAE overall healthy/0.95, MAE worst subgroup/10). This score selects regression models, not the optimisation objective.','', 'The GP posterior standard deviation or tree-to-tree spread guides exploratory sampling. Neither is claimed to be a calibrated confidence interval. The search pool combines 2,048 Sobol points across the full domain and 1,024 perturbed points near previously feasible trade-offs. Each active batch approximately divides into 12 predicted trade-off candidates, 6 uncertainty candidates and 6 unexplored candidates. All final 32 candidates use predicted trade-offs/feasibility ranking.','', '## Objectives and acceptance','', 'For each combination, maximise the lowest tumour killing across the three conditions. Minimise the highest overall healthy killing and highest individual healthy-subgroup killing. Require overall healthy killing ≤0.95% and every healthy subgroup ≤10% under every condition. Overall healthy killing is derived from subgroup predictions using fractions 0.79, 0.10, 0.10 and 0.01. No subgroup is dropped.','', 'Only ODE-evaluated points contribute to the reported trade-off front. Up to 12 high-tumour nondominated designs from each method receive tighter numerical checks. The main front uses the standard solver tolerances; tighter checks are reported separately. Returned combinations are best found at this small budget, not a proof of optimality.','', '## Results','', '| Seed | Selected model | ML best tumour (%) | Direct best tumour (%) | ML trade-off volume | Direct volume | ML time (s) | Direct time (s) |','|---|---|---:|---:|---:|---:|---:|---:|']
for a in runs:lines.append(f"| {a['seed']} | {a['selected_model']} | {a['assisted']['best_tumour']:.3f} | {a['direct']['best_tumour']:.3f} | {a['assisted']['hypervolume']:.4f} | {a['direct']['hypervolume']:.4f} | {a['timing']['assisted_total_wall']:.1f} | {a['timing']['direct_total_wall']:.1f} |")
lines+=['','Trade-off volume measures coverage in normalised utility coordinates (tumour/100, 1−overall/0.95, 1−subgroup/10), using the origin as the common reference. Higher is better. This depends on the chosen normalisation and supplements, rather than replaces, endpoint comparisons.','', 'Both methods use four ODE workers. Per-method elapsed times include initial data generation, subsequent search, regression fitting where applicable, and tighter final ODE checks. The table charges the full shared validation generation cost to ML for every seed. Test generation is common evaluation overhead and excluded from both methods. Batch size and solver variability affect timing. Three seeds provide preliminary evidence only.','',f"Shared validation simulation time (sum of calls): {r['shared_validation_seconds']:.1f} s. Shared test time (sum of calls): {r['shared_test_seconds']:.1f} s. These are computational costs even though shared across seeds. Initial benchmark phase wall time (before the extra fair-budget evaluations): {r['wall_seconds']:.1f} s.",'', '| Seed | Tumour MAE (pp) | Overall healthy MAE (pp) | Worst subgroup MAE (pp) | Predicted feasible / 64 | Actually infeasible among predicted feasible |','|---|---:|---:|---:|---:|---:|']
for a in runs:
 m=a['test_metrics'];lines.append(f"| {a['seed']} | {m['tumour']['mae_pp']:.3f} | {m['overall_healthy']['mae_pp']:.3f} | {m['worst_subgroup']['mae_pp']:.3f} | {m['predicted_feasible']} | {m['false_feasible']} |")
lines+=['','Percentage points are absolute differences in killing percentages, not percentage prediction accuracy. Full RMSE, R², per-subgroup errors, out-of-sample candidate errors and tight-check results are in results.json.','', '## Files and reproducibility','', 'Run repo/ml_small_trial/run_trial.py, then repo/ml_small_trial/fair_comparison.py, then repo/ml_small_trial/report_trial.py from the project environment. Use MPLBACKEND=Agg and one BLAS thread. Every evaluated input, predicted output and ODE output is saved in JSON. Configuration includes the model file hash. No previous optimised endpoint was supplied as a warm start.','', 'The comparator is small-budget NSGA-II without local refinement. This trial does not establish superiority over the existing longer NSGA-II plus local-refinement workflow. The trial is deliberately small. Model selection, sample size and candidate acquisition are pilot choices, not demonstrated optimal settings. Changing the biological conditions would require new training data or an independently assessed extension.']
lines += ['', '## What the trial supports', '', f'Regression-assisted search had greater trade-off coverage in {sum(a["assisted"]["hypervolume"]>a["direct"]["hypervolume"] for a in runs)} of {len(runs)} seeds. It had the higher best feasible tumour killing in {sum(a["assisted"]["best_tumour"]>a["direct"]["best_tumour"] for a in runs)} seeds. Mean elapsed time including the full validation charge was {ta:.1f} s for regression-assisted search and {td:.1f} s for direct search.', '', 'The comparison fixes the total simulation budget. It does not demonstrate fewer required ODE calls to reach a specified accuracy or trade-off quality. Runtime differences also reflect how expensive the selected binding-rate combinations are for the stiff ODE solver. Independent searches with other budgets would be needed to establish an efficiency curve.', '', f'Mean held-out prediction errors were {mae["tumour"]:.2f} percentage points for tumour killing, {mae["overall_healthy"]:.2f} for overall healthy killing and {mae["worst_subgroup"]:.2f} for the worst healthy subgroup. These errors must be judged against the 0.95% and 10% requirements, not just a high R².', '', f'The global test set contains only {runs[0]["test_metrics"]["actual_feasible"]} feasible combinations out of 64. It is a broad-domain approximation test and gives limited evidence about accuracy immediately around the healthy-cell limits. The selected-candidate predictions below expose errors during the search, before those points became training data.', '', '| Seed | Selected candidates | Predicted feasible | Actually infeasible among predicted feasible | Tight final checks passing: ML / direct |', '|---|---:|---:|---:|---|']
for a in runs:
 m=a['candidate_metrics'];lines.append(f"| {a['seed']} | {m['n']} | {m['predicted_feasible']} | {m['false_feasible']} | {a['assisted_tight_subset']['feasible']} / {a['direct_tight_subset']['feasible']} |")
lines += ['', 'No surrogate prediction alone should be accepted as meeting the healthy-cell requirements. Retain numerical ODE verification of every final combination. This is preliminary support for a search aid only, not for an autonomous affinity calculator, clinical accuracy, generalisation to new biology or a globally optimal range.', '', 'Only 12 selected points per method/seed receive tighter verification, so the full-front trade-off volume is not a tight-tolerance-certified result. Model-fitting warnings and model-selection scores are retained in results.json.']
(OUT/'Trial_report.md').write_text('\n'.join(lines))
nb=nbformat.v4.new_notebook();nb.cells=[nbformat.v4.new_markdown_cell('# Small regression-assisted binding-rate optimisation trial\n\nA completed pilot using the existing ODE model. Read `output/ml_small_trial/Trial_report.md` for assumptions and numerical results.'),nbformat.v4.new_code_cell("from pathlib import Path\nimport json\nfrom IPython.display import display, Markdown, Image\nroot = Path.cwd()\nif root.name == 'repo': root = root.parent\nresults = root / 'output' / 'ml_small_trial'\ndisplay(Markdown((results / 'Trial_report.md').read_text()))"),nbformat.v4.new_code_cell("for name in ['trial_flowchart','prediction_accuracy','search_comparison','predicted_vs_simulated']:\n    display(Image(filename=str(results / (name + '.png'))))"),nbformat.v4.new_markdown_cell('## Reproduction\nThe complete data-generation, preprocessing, model-selection and optimisation implementation is in `ml_small_trial/run_trial.py`. Run this only to repeat the trial; the cells above inspect saved results.\n\n```bash\nMPLBACKEND=Agg OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python repo/ml_small_trial/run_trial.py\npython repo/ml_small_trial/fair_comparison.py\npython repo/ml_small_trial/report_trial.py\n```')];nbformat.write(nb,ROOT/'repo/Bispecific_ADC_ML_Small_Trial.ipynb');print('Report and figures generated')
